2	export type ConnectionEvent = "open" | "close" | "message" | "error";
3	
4	export interface IConnectionTransportMap {
5	  open: WebSocketEventMap["open"];
6	  message: WebSocketEventMap["message"];
7	  close: WebSocketEventMap["close"];
8	  error: WebSocketEventMap["error"];
9	}
10	
11	export type ConnectionTransportCallback<T extends ConnectionEvent> = (
12	  data: IConnectionTransportMap[T],
13	) => void;
14	
15	export interface IConnectionTransport {
16	  reconnect(code?: number | undefined, reason?: string | undefined): void;
17	  close(): void;
18	  send(data: string | ArrayBuffer | Blob | ArrayBufferView): void;
19	  addEventListener<T extends ConnectionEvent>(
20	    event: T,
21	    callback: ConnectionTransportCallback<T>,
22	  ): void;
23	  removeEventListener<T extends ConnectionEvent>(
24	    event: T,
25	    callback: ConnectionTransportCallback<T>,
26	  ): void;
