11	
12	export class BasicTransport implements IConnectionTransport {
13	  private subscriptions = new ConnectionSubscriptions();
14	  private producer?: MessageProducer;
15	
16	  static withProducerCallback(producer: MessageProducer): IConnectionTransport {
17	    return new BasicTransport(producer);
18	  }
19	
20	  static empty(): IConnectionTransport {
21	    return new BasicTransport();
22	  }
23	
24	  private constructor(producer?: MessageProducer) {
25	    this.producer = producer;
26	  }
27	
28	  private startProducer() {
29	    if (this.producer) {
30	      this.producer((message) => {
31	        this.subscriptions.notify("message", message);
32	      });
33	    }
34	  }
35	
36	  private connect(): Promise<void> {
37	    return new Promise<void>((resolve) => setTimeout(resolve, 0)).then(() => {
38	      this.subscriptions.notify("open", new Event("open"));
39	    });
40	  }
