import ReconnectingWebSocket from "partysocket/ws";
import type {
  ConnectionEvent,
  ConnectionTransportCallback,
  IConnectionTransport,
} from "./transport";

// Per-`reconnect()` retry budget for partysocket. After exhaustion, partysocket
// stops silently; WsTransport rewrites the close reason to
// TRANSPORT_EXHAUSTED_REASON so downstream classification can detect the
// give-up without inspecting retry state.
export const MAX_RETRIES = 10;

// Synthetic close reason injected once the retry budget is exhausted. Recognized
// by `classifyCloseEvent` as the terminal "gave-up" signal.
export const TRANSPORT_EXHAUSTED_REASON = "MARIMO_TRANSPORT_EXHAUSTED";

type AnyCallback = (event: unknown) => void;

/**
 * A WebSocket transport wrapping a reconnecting WebSocket.
 *
 * Intercepts close events: when the inner socket has exhausted its retry
 * budget (`retryCount >= MAX_RETRIES`), the close event's reason is rewritten
 * to {@link TRANSPORT_EXHAUSTED_REASON} before being delivered to listeners.
 * This rewrite applies even when the original close event carried a
 * server-sent reason.
 */
export class WsTransport implements IConnectionTransport {
  private inner: ReconnectingWebSocket;

  // Maps a registered callback to the wrapper actually attached to the inner
  // socket, per event type. Used both to deduplicate registrations and to
  // fully unregister a callback (removing its wrapper from the inner socket).
  private wrappers = new Map<ConnectionEvent, Map<AnyCallback, AnyCallback>>();

  constructor(urlFactory: () => string) {
    this.inner = new ReconnectingWebSocket(urlFactory, undefined, {
      maxRetries: MAX_RETRIES,
      debug: false,
      startClosed: true,
      // long timeout -- the server can become slow when many notebooks
      // are open.
      connectionTimeout: 10_000,
    });
  }

  get readyState(): WebSocket["readyState"] {
    return this.inner.readyState as WebSocket["readyState"];
  }

  get retryCount(): number {
    return this.inner.retryCount;
  }

  reconnect(code?: number | undefined, reason?: string | undefined): void {
    this.inner.reconnect(code, reason);
  }

  close(): void {
    this.inner.close();
  }

  send(data: string | ArrayBuffer | Blob | ArrayBufferView): void {
    this.inner.send(data);
  }

  addEventListener<T extends ConnectionEvent>(
    event: T,
    callback: ConnectionTransportCallback<T>,
  ): void {
    const cb = callback as AnyCallback;
    let byCallback = this.wrappers.get(event);
    if (!byCallback) {
      byCallback = new Map();
      this.wrappers.set(event, byCallback);
    }
    // Deduplicate: the same callback reference must only fire once per event.
    if (byCallback.has(cb)) {
      return;
    }

    const wrapper =
      event === "close" ? this.makeCloseWrapper(cb) : cb;
    byCallback.set(cb, wrapper);
    this.inner.addEventListener(event as never, wrapper as never);
  }

  removeEventListener<T extends ConnectionEvent>(
    event: T,
    callback: ConnectionTransportCallback<T>,
  ): void {
    const cb = callback as AnyCallback;
    const byCallback = this.wrappers.get(event);
    if (!byCallback) {
      return;
    }
    const wrapper = byCallback.get(cb);
    if (!wrapper) {
      return;
    }
    // Fully unregister with a single call: because registration is
    // deduplicated, exactly one wrapper is attached to the inner socket, so
    // removing it leaves no orphaned listeners behind.
    this.inner.removeEventListener(event as never, wrapper as never);
    byCallback.delete(cb);
  }

  private makeCloseWrapper(callback: AnyCallback): AnyCallback {
    return (event: unknown) => {
      // Once the retry budget is exhausted, partysocket stops reconnecting
      // silently. Rewrite the reason so downstream classification can detect
      // the give-up. This overrides any server-sent reason.
      if (this.inner.retryCount >= MAX_RETRIES) {
        callback(rewriteCloseReason(event, TRANSPORT_EXHAUSTED_REASON));
        return;
      }
      callback(event);
    };
  }
}

/**
 * Returns a close event equivalent to `event` but with its reason replaced.
 * The original event's reason cannot be mutated (CloseEvent.reason is
 * read-only), so a new event is constructed.
 */
function rewriteCloseReason(event: unknown, reason: string): unknown {
  const original = event as {
    code?: number;
    reason?: string;
    wasClean?: boolean;
  };
  try {
    return new CloseEvent("close", {
      code: original.code,
      reason,
      wasClean: original.wasClean,
    });
  } catch {
    // Fallback for environments without a CloseEvent constructor.
    return {
      type: "close",
      code: original.code,
      reason,
      wasClean: original.wasClean,
    };
  }
}
