function makeTransport() {
  const t = new WsTransport(() => "ws://localhost/ws");
  const inner = (t as unknown as { inner: EventTarget & { retryCount: number } })
    .inner;
  return { t, inner };
}

describe("WsTransport scratch", () => {
  it("exports constants", () => {
    expect(TRANSPORT_EXHAUSTED_REASON).toBe("MARIMO_TRANSPORT_EXHAUSTED");
