    const { t, inner } = makeTransport();
    Object.defineProperty(inner, "retryCount", { get: () => MAX_RETRIES });
    const cb = vi.fn();
    t.addEventListener("close", cb);
    inner.dispatchEvent(new CloseEvent("close", { reason: "server-said-bye" }));
