    Object.defineProperty(inner, "retryCount", { get: () => 0 });
    const cb = vi.fn();
    t.addEventListener("close", cb);
    inner.dispatchEvent(new CloseEvent("close", { reason: "transient" }));
    expect(cb.mock.calls[0][0].reason).toBe("transient");
  });

